const AUTO_FX = [[/生日快乐/, 'balloons'], [/恭喜|祝贺/, 'confetti'], [/新年快乐|元旦快乐|春节快乐/, 'fireworks'], [/爱你|想你|❤|love you/i, ''], [/pew pew/i, 'lasers']];
M.send = async (id, opt) => {
