    const fm = FMT[id] || {}; const m = addMsg(t, { from: 'me', text: tx.slice(0, 2000), reply: REP[id] || '', fx: t.sms ? '' : fx, urgent: opt && opt.urgent, fmt: (fm.b || fm.i || fm.u || fm.s) ? { b: fm.b, i: fm.i, u: fm.u, s: fm.s } : null, tfx: t.sms ? '' : fm.tfx || '' });
